import os

import torch
from torch.utils.cpp_extension import load_inline

from task import input_t, output_t


_CPP = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContextLight.h>
#include <ATen/ops/triu.h>
#include <cublas_v2.h>
#include <cusolverDn.h>

namespace {

void check_cusolver(cusolverStatus_t status, const char* what) {
    TORCH_CHECK(status == CUSOLVER_STATUS_SUCCESS, what, " failed with status ",
                static_cast<int>(status));
}

} // namespace

torch::Tensor direct_cholesky(
        torch::Tensor input,
        torch::Tensor output,
        torch::Tensor pointers,
        torch::Tensor info,
        torch::Tensor workspace) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(input.scalar_type() == at::kFloat, "input must be float32");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(input.dim() == 3 && input.size(1) == input.size(2),
                "input must be a batch of square matrices");
    TORCH_CHECK(output.is_cuda() && output.scalar_type() == at::kFloat,
                "output must be CUDA float32");
    TORCH_CHECK(output.is_contiguous() && output.sizes() == input.sizes(),
                "output must be a same-sized contiguous tensor");

    const int batch = static_cast<int>(input.size(0));
    const int n = static_cast<int>(input.size(1));
    // cuSOLVER's column-major lower triangle is the row-major upper triangle.
    // Copy just that source triangle and zero the unused half in one kernel.
    at::triu_out(output, input, 0);
    TORCH_CHECK(info.is_cuda() && info.scalar_type() == at::kInt &&
                info.numel() == batch, "invalid info tensor");
    auto handle = at::cuda::getCurrentCUDASolverDnHandle();
    check_cusolver(
        cusolverDnSetMathMode(handle, CUSOLVER_FP32_EMULATED_BF16X9_MATH),
        "cusolverDnSetMathMode");

    const bool use_looped = batch <= 4 && n >= 1024;
    if (!use_looped) {
        TORCH_CHECK(pointers.is_cuda() &&
                    pointers.scalar_type() == at::kLong &&
                    pointers.numel() == batch, "invalid pointer array");
        check_cusolver(
            cusolverDnSpotrfBatched(
                handle, CUBLAS_FILL_MODE_LOWER, n,
                reinterpret_cast<float**>(pointers.data_ptr<int64_t>()), n,
                info.data_ptr<int>(), batch),
            "cusolverDnSpotrfBatched");
    } else {
        TORCH_CHECK(workspace.is_cuda() &&
                    workspace.scalar_type() == at::kFloat,
                    "invalid workspace tensor");
        const int64_t matrix_stride = static_cast<int64_t>(n) * n;
        for (int i = 0; i < batch; ++i) {
            check_cusolver(
                cusolverDnSpotrf(
                    handle, CUBLAS_FILL_MODE_LOWER, n,
                    output.data_ptr<float>() + i * matrix_stride, n,
                    workspace.data_ptr<float>(), workspace.numel(),
                    info.data_ptr<int>() + i),
                "cusolverDnSpotrf");
        }
    }

    // The row-major upper factor becomes an F-contiguous lower-triangular view.
    return output.transpose(-2, -1);
}

int64_t workspace_size(torch::Tensor input) {
    const int n = static_cast<int>(input.size(-1));
    int lwork = 0;
    auto handle = at::cuda::getCurrentCUDASolverDnHandle();
    check_cusolver(
        cusolverDnSetMathMode(handle, CUSOLVER_FP32_EMULATED_BF16X9_MATH),
        "cusolverDnSetMathMode");
    check_cusolver(
        cusolverDnSpotrf_bufferSize(
            handle, CUBLAS_FILL_MODE_LOWER, n, input.data_ptr<float>(), n,
            &lwork),
        "cusolverDnSpotrf_bufferSize");
    return lwork;
}
"""


_TORCH_LIB = os.path.join(os.path.dirname(torch.__file__), "lib")


_ext = load_inline(
    name="cholesky_direct_cusolver_v11",
    cpp_sources=_CPP,
    functions=["direct_cholesky", "workspace_size"],
    extra_cflags=["-O3"],
    extra_ldflags=[
        "-ltorch_cuda_linalg",
        "-l:libcusolver.so.12",
        f"-Wl,-rpath,{_TORCH_LIB}",
    ],
    with_cuda=True,
    verbose=False,
)


_active_shape = None
_output_cache = {}
_info = None
_workspace = None


def custom_kernel(data: input_t) -> output_t:
    global _active_shape, _info, _workspace
    if data.shape[-1] >= 32:
        shape = tuple(data.shape)
        if shape != _active_shape:
            _output_cache.clear()
            _active_shape = shape
            _info = torch.empty(data.shape[0], device=data.device, dtype=torch.int32)
            use_looped = data.shape[0] <= 4 and data.shape[-1] >= 1024
            if use_looped:
                lwork = _ext.workspace_size(data)
                _workspace = torch.empty(lwork, device=data.device, dtype=torch.float32)
            else:
                _workspace = torch.empty(0, device=data.device, dtype=torch.float32)
        key = id(data)
        entry = _output_cache.get(key)
        if entry is None or entry[0] is not data:
            output = torch.empty_like(data, memory_format=torch.contiguous_format)
            if data.shape[0] > 1:
                step = data.shape[-1] * data.shape[-1] * data.element_size()
                pointers = torch.arange(
                    output.data_ptr(),
                    output.data_ptr() + data.shape[0] * step,
                    step,
                    device=data.device,
                    dtype=torch.int64,
                )
            else:
                pointers = torch.empty(0, device=data.device, dtype=torch.int64)
            _output_cache[key] = (data, output, pointers)
        else:
            output, pointers = entry[1], entry[2]
        return _ext.direct_cholesky(data, output, pointers, _info, _workspace)
    return torch.linalg.cholesky_ex(data, check_errors=False).L

