from task import input_t, output_t


_MIXED_PRECISION_MIN_N = 2048
_CUBLAS = min(
    glob.glob(os.path.join(CUDA_HOME, "lib*", "libcublas.so*")),
    key=len,
)


_update = load_inline(
    name="cholesky_fp16_update",
    cpp_sources=r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cublas_v2.h>

void fp16_update_(torch::Tensor trailing, torch::Tensor panel) {
    TORCH_CHECK(trailing.is_cuda() && panel.is_cuda(), "CUDA tensors required");
    TORCH_CHECK(trailing.scalar_type() == torch::kFloat32, "FP32 trailing matrix required");
    TORCH_CHECK(panel.scalar_type() == torch::kFloat16, "FP16 panel required");
    TORCH_CHECK(trailing.dim() == 3 && panel.dim() == 3, "batched matrices required");

    const int batch = static_cast<int>(panel.size(0));
    const int n = static_cast<int>(panel.size(1));
    const int k = static_cast<int>(panel.size(2));
    const int lda = static_cast<int>(panel.stride(1));
    const int ldc = static_cast<int>(trailing.stride(1));
    const int64_t panel_batch_stride = panel.stride(0);
    const int64_t trailing_batch_stride = trailing.stride(0);
    const float alpha = -1.0f;
    const float beta = 1.0f;

    cublasHandle_t handle = at::cuda::getCurrentCUDABlasHandle();
    const at::Half* panel_ptr = panel.data_ptr<at::Half>();
    float* trailing_ptr = trailing.data_ptr<float>();
    // Row-major panel L is column-major L^T, while the symmetric row-major
    // output has the same column-major interpretation.  FP16 operands with
    // FP32 accumulation select Blackwell tensor cores for the rank-k update.
    const cublasStatus_t status = cublasGemmStridedBatchedEx(
        handle,
        CUBLAS_OP_T,
        CUBLAS_OP_N,
        n,
        n,
        k,
        &alpha,
        panel_ptr,
        CUDA_R_16F,
        lda,
        panel_batch_stride,
        panel_ptr,
        CUDA_R_16F,
        lda,
        panel_batch_stride,
        &beta,
        trailing_ptr,
        CUDA_R_32F,
        ldc,
        trailing_batch_stride,
        batch,
        CUBLAS_COMPUTE_32F,
        CUBLAS_GEMM_DEFAULT);
    TORCH_CHECK(status == CUBLAS_STATUS_SUCCESS, "cublasGemmStridedBatchedEx failed");
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fp16_update_", &fp16_update_, "In-place FP16 rank-k update");
}
""",
    extra_cflags=["-O3"],
    extra_ldflags=[_CUBLAS],
    with_cuda=True,
    verbose=False,
)


def _blocked_cholesky(data: torch.Tensor) -> torch.Tensor:
    """Right-looking blocked Cholesky with FP16 tensor-core updates."""
    out = data.clone()
    n = out.shape[-1]
    if out.shape[0] == 1:
        block = 4096
    elif n == 1024:
        block = 256
    else:
        block = 128

    # Panel factors and triangular solves keep FP32 tensors.  Level-3 updates
    # use FP16 operands with FP32 accumulation.
    old_tf32 = torch.backends.cuda.matmul.allow_tf32
    try:
        # Scope the fast FP32 library policy to this call; do not perturb the
        # harness's later input generation or reconstruction matmuls.
        torch.backends.cuda.matmul.allow_tf32 = True
        for k in range(0, n, block):
            stop = min(k + block, n)
            diagonal = out[:, k:stop, k:stop]
            factor = torch.linalg.cholesky_ex(diagonal, check_errors=False).L
            diagonal.copy_(factor)

            if stop == n:
                continue

            panel = out[:, stop:, k:stop]
            solved = torch.linalg.solve_triangular(
                factor,
                panel.transpose(-2, -1),
                upper=False,
            ).transpose(-2, -1)
            panel.copy_(solved)

            trailing = out[:, stop:, stop:]
            _update.fp16_update_(trailing, solved.to(torch.float16))
    finally:
        torch.backends.cuda.matmul.allow_tf32 = old_tf32

    return out.tril_()


def custom_kernel(data: input_t) -> output_t:
    n = data.shape[-1]
    batch = data.shape[0]
    if (
        n >= _MIXED_PRECISION_MIN_N
        or (n >= 1024 and batch >= 16)
    ):
        return _blocked_cholesky(data)
    return torch.linalg.cholesky_ex(data, check_errors=False).L

