def _block_size(batch: int, n: int) -> int:
    if batch == 1:
        return 4096
    if n == 1024:
        return 256
    return 128


def _blocked_cholesky(
    data: torch.Tensor,
    output: torch.Tensor,
) -> torch.Tensor:
    output.copy_(data)
    n = output.shape[-1]
    block = _block_size(output.shape[0], n)

    old_tf32 = torch.backends.cuda.matmul.allow_tf32
    try:
        torch.backends.cuda.matmul.allow_tf32 = True
        for k in range(0, n, block):
            stop = min(k + block, n)
            diagonal = output[:, k:stop, k:stop]
            factor = torch.linalg.cholesky_ex(
                diagonal, check_errors=False
            ).L
            diagonal.copy_(factor)
            if stop == n:
                continue

            panel = output[:, stop:, k:stop]
            solved = torch.linalg.solve_triangular(
                factor,
                panel.transpose(-2, -1),
                upper=False,
