        shape = tuple(data.shape)
        if shape != _active_shape:
            _output_cache.clear()
            _active_shape = shape
            if use_mixed:
                _info = torch.empty(0, device=data.device, dtype=torch.int32)
                _workspace = torch.empty(0, device=data.device, dtype=torch.float32)
            else:
                _info = torch.empty(
